def build_rows() -> list[dict]:
    rows = []
    for slug, canonical, aliases, implies, ambiguous, context in S:
        rows.append(dict(kind="skill", slug=slug, canonical=canonical, aliases=aliases, implies=implies,
                         ambiguous=ambiguous, context=context, description=""))
    for slug, canonical, aliases, ambiguous, context, description in T:
        rows.append(dict(kind="topic", slug=slug, canonical=canonical, aliases=aliases, implies="",
                         ambiguous=ambiguous, context=context, description=description))
    return rows


def lint(rows: list[dict]) -> list[str]:
    problems = []
    slugs = {r["slug"] for r in rows}
    if len(slugs) != len(rows):
        problems.append("duplicate slugs")
    owner: dict[str, str] = {}
    for r in rows:
        forms = [r["canonical"]] + [a for a in r["aliases"].split("|") if a]
        for f in forms:
            key = f.lower()
            if key in owner and owner[key] != r["slug"]:
                problems.append(f"surface form {f!r} belongs to both {owner[key]} and {r['slug']}")
            owner[key] = r["slug"]
        for amb in [a for a in r["ambiguous"].split("|") if a]:
            if amb.lower() not in {x.lower() for x in forms}:
                problems.append(f"{r['slug']}: ambiguous form {amb!r} is not one of its surface forms")
            if not r["context"]:
                problems.append(f"{r['slug']}: ambiguous form {amb!r} but no context words")
        for imp in [i for i in r["implies"].split("|") if i]:
            if imp not in slugs:
                problems.append(f"{r['slug']}: implies unknown term {imp!r}")
            if imp == r["slug"]:
                problems.append(f"{r['slug']}: implies itself")
    return problems


def main() -> int:
    rows = build_rows()
    problems = lint(rows)
    if problems:
        print("vocab seed is inconsistent:\n  " + "\n  ".join(problems))
        return 1
    out = Path(__file__).resolve().parents[1] / "schema" / "vocab.csv"
    out.parent.mkdir(parents=True, exist_ok=True)
    with out.open("w", newline="", encoding="utf-8") as f:
        w = csv.DictWriter(f, fieldnames=["kind", "slug", "canonical", "aliases", "implies", "ambiguous", "context", "description"])
        w.writeheader()
        w.writerows(rows)
    n_skill = sum(1 for r in rows if r["kind"] == "skill")
    n_topic = len(rows) - n_skill
    n_forms = sum(1 + (len(r["aliases"].split("|")) if r["aliases"] else 0) for r in rows)
    print(f"wrote {out}: {n_skill} skills, {n_topic} topics, {n_forms} surface forms")
    return 0


if __name__ == "__main__":
    sys.exit(main())
